import { useState } from "react";
import { ArrowUp } from "lucide-react";
import { ask, type Answer } from "@/ai/ask";
import { getAIProvider } from "@/ai/provider";
import { useAccounts, useBudgets, useCategories, useCategoryMap, useTransactions } from "@/db/hooks";
import { useI18n } from "@/i18n";
import { categoryName } from "@/lib/labels";
import { Money } from "./Money";

const EXAMPLES = ["ask.ex1", "ask.ex2", "ask.ex3", "ask.ex4", "ask.ex5"];

/**
 * Ask Ledger. Answers are computed deterministically from your ledger; nothing
 * here is generated by a model. An AI provider, when configured, can only add
 * an explanation on top (see ReportSheet).
 */
export function AskLedger() {
  const { t, currency, pct } = useI18n();
  const txns = useTransactions() ?? [];
  const categories = useCategories();
  const budgets = useBudgets();
  const accounts = useAccounts();
  const cats = useCategoryMap();
  const [q, setQ] = useState("");
  const [answer, setAnswer] = useState<{ q: string; a: Answer } | null>(null);
  const provider = getAIProvider();

  const run = (question: string) => {
    if (!question.trim()) return;
    const a = ask(question, { txns, categories, budgets, accounts, currency }, (c) => [c.name, categoryName(c, t)]);
    setAnswer({ q: question, a });
  };
  const cn = (id: string | null) => (id === "_fees" ? t("insights.transferFees") : id === "_none" ? t("insights.uncategorised") : categoryName(cats.get(id ?? ""), t));

  return (
    <div className="px-5">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          run(q);
        }}
        className="relative"
      >
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t("ask.placeholder")}
          className="h-11 w-full rounded border border-rule-strong bg-surface pe-11 ps-3 text-base outline-none placeholder:text-ink-4 focus:border-accent"
          enterKeyHint="send"
        />
        <button type="submit" aria-label={t("ask.send")} className="absolute end-1.5 top-1.5 flex size-8 items-center justify-center rounded-sm bg-ink text-paper disabled:opacity-30" disabled={!q.trim()}>
          <ArrowUp className="size-4" />
        </button>
      </form>
      <div className="-mx-5 mt-2 flex gap-1.5 overflow-x-auto px-5 pb-1 no-scrollbar">
        {EXAMPLES.map((k) => (
          <button
            key={k}
            onClick={() => {
              setQ(t(k));
              run(t(k));
            }}
            className="h-7 shrink-0 rounded-sm border border-rule-strong px-2.5 text-xs text-ink-2"
          >
            {t(k)}
          </button>
        ))}
      </div>

      {answer && (
        <div className="mt-4 border-s-2 border-ink ps-3">
          <div className="text-xs text-ink-3">“{answer.q}”</div>
          <div className="mt-1.5 text-base leading-relaxed">
            {answer.a.type === "top_category" &&
              (answer.a.categoryId ? (
                <>
                  {t("ask.top", { cat: cn(answer.a.categoryId), period: t(`period.${answer.a.period.label}`), share: pct(answer.a.share) })} <Money value={answer.a.amount} cents={false} className="font-medium" />
                </>
              ) : (
                t("ask.nothing")
              ))}
            {answer.a.type === "category_total" && (
              <>
                {t("ask.catTotal", { cat: cn(answer.a.categoryId), period: t(`period.${answer.a.period.label}`), count: answer.a.count })} <Money value={answer.a.amount} cents={false} className="font-medium" />
              </>
            )}
            {answer.a.type === "income_from" && (
              <>
                {t("ask.incomeFrom", { from: answer.a.label === "all" ? t("ask.allSources") : cn(answer.a.label), period: t(`period.${answer.a.period.label}`), count: answer.a.count })}{" "}
                <Money value={answer.a.amount} cents={false} className="font-medium" tone="pos" />
              </>
            )}
            {answer.a.type === "compare" && (
              <>
                {t("ask.compareSpend")} <Money value={answer.a.spending[0]} cents={false} className="font-medium" /> {t("ask.vs")} <Money value={answer.a.spending[1]} cents={false} tone="muted" />. {t("ask.compareIncome")}{" "}
                <Money value={answer.a.income[0]} cents={false} className="font-medium" /> {t("ask.vs")} <Money value={answer.a.income[1]} cents={false} tone="muted" />.
              </>
            )}
            {answer.a.type === "overspend" &&
              (answer.a.over.length ? (
                <>
                  {t("ask.overIntro")}
                  <ul className="mt-1 space-y-0.5">
                    {answer.a.over.map((o) => (
                      <li key={o.categoryId} className="flex justify-between gap-3 text-sm">
                        <span>{cn(o.categoryId)}</span>
                        <span>
                          <Money value={o.amount} cents={false} size="sm" /> <span className="text-ink-3">({t("ask.was")} <Money value={o.previous} cents={false} size="sm" tone="muted" />)</span>
                        </span>
                      </li>
                    ))}
                  </ul>
                </>
              ) : (
                t("ask.noOverspend")
              ))}
            {answer.a.type === "unsupported" && <span className="text-ink-2">{t("ask.unsupported")}</span>}
          </div>
          {answer.a.type !== "unsupported" && <div className="mt-2 text-2xs uppercase tracking-wider text-ink-4">{t("ask.computed")}</div>}
        </div>
      )}
      <p className="mt-4 text-xs leading-relaxed text-ink-4">{provider ? t("ask.aiAvailable") : t("ask.aiOff")}</p>
    </div>
  );
}
